INSERT INTO Language_en_US (Tag, Text) VALUES
 ('TXT_KEY_COVENANT_DESC', 'The Covenant'),
 ('TXT_KEY_COVENANT_SHORT', 'Covenant'),
 ('TXT_KEY_COVENANT_ADJECTIVE', 'Covenant'),
 ('TXT_KEY_COVENANT_PEDIA', 'A fictional civilization built around the study, recall, and practice of Scripture. Its five passages connect wealth, sanctuary, covenant, heavenly patterns, and belief.'),
 ('TXT_KEY_COVENANT_STRATEGY', 'Build Scriptoria and Tabernacles for Faith, Culture, and Science. Mandatory typed recall unlocks your turn. Unaided reviews grant Faith and Culture, once per turn. Learn all five passages and keep them through recurring exams.'),
 ('TXT_KEY_COVENANT_DAWN', 'Scribe, your people possess ink, scrolls, and a dangerous appetite for one more turn. Lead them from a copy and shadow toward understanding. Gold can fill a treasury; remembered words can fill a life. Study five passages, speak them, and recall them faithfully. Your next turn must be earned.'),
 ('TXT_KEY_COVENANT_LEADER', 'The Scribe'),
 ('TXT_KEY_COVENANT_LEADER_PEDIA', 'The Scribe is a fictional leader who turns every campaign into a Scripture memory course. Among codices, scrolls and lamplight, he teaches that patient study must become remembered words.'),
 ('TXT_KEY_CIV5_COVENANT_HEADING_1', 'Written on the Heart'),
 ('TXT_KEY_CIV5_COVENANT_TEXT_1', 'A fictional people devoted to learning and recalling Scripture. Their treasury rewards accurate memory, and their next turn waits until the required passage is recalled.'),
 ('TXT_KEY_CIVILOPEDIA_LEADERS_COVENANT_NAME', 'The Scribe'),
 ('TXT_KEY_CIVILOPEDIA_LEADERS_COVENANT_SUBTITLE', 'Keeper of the Covenant'),
 ('TXT_KEY_CIVILOPEDIA_LEADERS_COVENANT_LIVED', 'A fictional leader beyond a single historical era'),
 ('TXT_KEY_CIVILOPEDIA_LEADERS_COVENANT_TITLES_1', 'Student, Scribe, and Keeper'),
 ('TXT_KEY_CIVILOPEDIA_LEADERS_COVENANT_HEADING_1', 'One More Verse'),
 ('TXT_KEY_CIVILOPEDIA_LEADERS_COVENANT_TEXT_1', 'The Scribe leads a civilization built for personal Bible memorisation. His scriptorium is a place of ink, parchment and patient study. Recall the reference and every word of each passage to unlock play.'),
 ('TXT_KEY_COVENANT_TRAIT_SHORT', 'Written on the Heart'),
 ('TXT_KEY_COVENANT_TRAIT', '+1 [ICON_CULTURE] Culture in each city. Successfully recall a passage without study or mistakes to earn 10 [ICON_PEACE] Faith and 5 [ICON_CULTURE] Culture per era, at most once per turn. Mandatory typed memory checks block play until passed; an all-five exam returns every ten turns.'),
 ('TXT_KEY_COVENANT_SCRIPTORIUM', 'Scriptorium'),
 ('TXT_KEY_COVENANT_SCRIPTORIUM_PEDIA', 'A place for copying and studying sacred texts. Beneath sandstone arches and navy awnings, scribes work by lamplight among codices and rolled parchments. Replaces the Shrine.'),
 ('TXT_KEY_COVENANT_SCRIPTORIUM_STRATEGY', 'The Scriptorium replaces the Shrine and provides 2 Faith and 1 Culture per turn. Its cost, technology and maintenance match the Shrine.'),
 ('TXT_KEY_COVENANT_SCRIPTORIUM_HELP', '2 [ICON_PEACE] Faith and 1 [ICON_CULTURE] Culture. Replaces the Shrine.'),
 ('TXT_KEY_COVENANT_TABERNACLE', 'Tabernacle'),
 ('TXT_KEY_COVENANT_TABERNACLE_PEDIA', 'A sanctuary recalling the tabernacle and its heavenly pattern. Ivory-and-navy linen hangings and golden fittings frame a quiet place of worship. Replaces the Temple.'),
 ('TXT_KEY_COVENANT_TABERNACLE_STRATEGY', 'The Tabernacle replaces the Temple and provides 3 Faith and 1 Science per turn. Its cost, technology, maintenance and prerequisite building classes match the Temple.'),
 ('TXT_KEY_COVENANT_TABERNACLE_HELP', '3 [ICON_PEACE] Faith and 1 [ICON_RESEARCH] Science. Replaces the Temple.'),
 ('TXT_KEY_COVENANT_CITY_1', 'Laodicea'),
 ('TXT_KEY_COVENANT_CITY_2', 'Most Holy Place'),
 ('TXT_KEY_COVENANT_CITY_3', 'Messenger''s Rest'),
 ('TXT_KEY_COVENANT_CITY_4', 'Mountain Pattern'),
 ('TXT_KEY_COVENANT_CITY_5', 'Foretold'),
 ('TXT_KEY_COVENANT_CITY_6', 'Refined Gold'),
 ('TXT_KEY_COVENANT_CITY_7', 'White Garments'),
 ('TXT_KEY_COVENANT_CITY_8', 'Clear Sight'),
 ('TXT_KEY_COVENANT_CITY_9', 'Covenant Gate'),
 ('TXT_KEY_COVENANT_CITY_10', 'Sanctuary');
